                                     //   whatever the team size; the front part keeps the rest and sheds again as soon as it may
    double CT = 0;                   // 1: TRADES BY HEAD COUNT - whether to start a head-on is decided by the heads around it:
    double CT_R = 6;                 //   outnumbered (their heads within CT_R steps of mine against ours, me included): never. A
    double CT_NEAR = 3;              //   longer enemy: only where our other heads within CT_NEAR of its head are not fewer than
    double CT_MAXLEN = 8;            //   theirs (the drops go to whoever is there). One about my length (I am at most CT_TOL longer
    double CT_TOL = 1;               //   and shorter than CT_MAXLEN): when we outnumber them in view, or outnumber them at its head
    double CT_LUNGE = 5;             //   with ours the nearer, or - I am CT_LUNGE or shorter - at parity there with a mate within
                                     //   CT_NEAR and ours the nearer. Replaces the length rules (RAM_DOWN, EVEN_NEEDS_FRIENDS)
    double CT_FEAR = 0;              // x > 0: outnumbered in view (their heads > ours, me included) every enemy head is a threat
                                     //   of at least stake x, whatever its length
    double CT_FEAR_M = 1;            //   ... outnumbered = their heads in view are at least ours (me included) + CT_FEAR_M
                                     //   (1: more of them than of us; 0: as many as us is enough)
    double CT_FEAR_TOL = 99;         //   ... and only a head at most CT_FEAR_TOL longer than I am (one much longer than me loses
                                     //   more than it kills: it has no reason to start the trade)
    double BLOCK_PEN = 0.4;          // the food a step loses when it lands on a tile whose timer fires while I am on it (was 0.4)
    double RESPAWN_W = 0;            // x > 0: a pearl whose tile tries to spawn again within RESPAWN_WIN rounds of my eating it is
    double RESPAWN_WIN = 8;          //   worth x more (left there, the next try is wasted on an occupied tile); for dragons of
    double RESPAWN_MAXLEN = 7;       //   RESPAWN_MAXLEN or shorter
    double QH_NEAR = 0;              // n > 0: a fresh sighting of their queen close by is a target at any round - at most
    double QH_NEAR_AGE = 6;          //   QH_NEAR_AGE rounds old, within n steps, for a dragon of QH_NEAR_LEN or shorter (no lead
    double QH_NEAR_LEN = 10;         //   test); the spotter calls it out and others pass the call on from round 0
    double Q_RUN = 0;                // n > 0: THE QUEEN KEEPS A RUN - on every map a queen's step after which she cannot make n
    double Q_RUN_PEN = 3.0;          //   more moves with every other dragon frozen in place costs Q_RUN_PEN per missing move
    double APART = 0;                // x > 0: KEEP APART - every friendly head in view pushes me away: a step gains x for each step
    double APART_CAP = 7;            //   of distance (rows + columns in view, at most APART_CAP) it puts between my head and that
    double APART_UNTIL = 300;        //   head; a step out of view through a portal counts as APART_CAP from all of them. Before
    double APART_MAXLEN = 99;        //   round APART_UNTIL, for dragons of APART_MAXLEN or shorter; not the queen, the king, a
    double APART_Q = 1;              //   hunter, a guard or a dragon on an errand. APART_Q 0: our queen's head does not push
    double APART_PORT = 1;           //   APART_PORT: the share of that gain a step through a portal gets (0: none)
    double MG_TQD = 3;               // THE GATHERING LEAVES THE HUNTERS OUT - 1: no gathering while their queen is not known dead (her death
    double MG_TQD_LEAD = 40;         //   is worth more than our length: the hunt goes on); 2: then only a dragon with a sighting of
                                     //   her at most MG_TQD_LEAD rounds old, or that knows our own queen dead, stays out of it;
                                     //   3: only the dragon with such a sighting stays out
    std::vector<std::array<int, 3>> cheat_portals;   // CHEAT_PORTALS: [(kind, tile, portal id)]
    std::vector<MapOvr> map_ovr = {{6, &Params::ORA_W, 25.0}, {17, &Params::OE_AREA, 99999.0}};                      // (8 Oct, ORA) "M<k>:NAME" overrides
    std::vector<AreaOvr> area_ovr = {{4000.0, 1, &Params::BIGKEEP_LEN, 16.0}, {1100.0, 0, &Params::FRIEND_CLAIM, 1.0}, {4000.0, 1, &Params::Q_HOME_HUNGRY, 30.0}, {1100.0, 0, &Params::Q_SPLIT_UNTIL, 200.0}, {1100.0, 1, &Params::Q_NOPORT, 1.0}, {1100.0, 1, &Params::Q_NORAM_ALL, 1.0}, {1100.0, 0, &Params::LANE_EARLY, 1.0}, {1100.0, 0, &Params::QRES, 3.0}, {4000.0, 0, &Params::Q_KING, 0.0}};                    // (7 Oct) "A<n>:NAME" / "B<n>:NAME" overrides
